// Metres for the default 4.2 × 1.8 × 1.45 m car. x = forward, y = up, z = right. Scaled per axis for other sizes.
const TPL = { R: 0.33, WW: 0.23, AXF: 1.30, AXR: -1.30, WZ: 0.755, ARCH: 0.39, CRUSH: 0.26, XC0: 1.66, XF: 1.97 };
function archBottom(x, xa, base) {
  const d = Math.abs(x - xa);
  return d < TPL.ARCH ? Math.max(base, TPL.R + Math.sqrt(TPL.ARCH * TPL.ARCH - d * d)) : base;
}

// Bond thresholds: F = latched/fixed stage, H = hinge stage, as [yield N, overload impulse N·s, ultimate N].
function carSpec() {
  const P = [];
  const B = (x0, x1, y0, y1, z0, z1) => ({ t: 'box', b: [x0, x1, y0, y1, z0, z1] });
