// ============================================================ simulation run
class Sim {
  constructor(cfg) {
    this.cfg = { ...cfg };
    const c = this.cfg, L = c.trackLength, wallFront = L / 2 - 7;
    this.layout = {
      x0: -L / 2, x1: L / 2, wallFront, carRear: -L / 2 + 1.5, carLen: c.carLength, carWid: c.carWidth, carZ: 0.35,
      startLine: -L / 2 + 1.5 + c.carLength + 0.6, runoffEnd: wallFront + 28,
      zB: Math.max(9.5, (c.wallCols * c.brickW) / 2 + 2.5),
    };
    this.world = new RAPIER.World({ x: 0, y: -c.gravity, z: 0 });
    this.world.timestep = DT;
    const ip = this.world.integrationParameters;
    ip.numSolverIterations = 8;
    ip.maxCcdSubsteps = 2;
    this.eq = new RAPIER.EventQueue(true);
    this.owners = new Map();
    this.group = new THREE.Group();
    scene.add(this.group);
    this.tracked = []; this.parts = []; this.partById = {}; this.bricks = []; this.shards = [];
    this.stepIndex = 0; this.time = 0; this.phase = 'idle';
    this.releaseT = null; this.impactT = null; this.cmdV = 0; this.driveStep = 0;
    this.crushD = 0; this.dVis = 0; this.dApplied = -1;
    this.shake = 0; this.aHist = []; this.settleCount = 0; this.dustBudget = 0; this.sparkBudget = 0;
    this.stats = { impactSpeed: null, peakG: 0, detached: 0, panes: 0, shards: 0, bricksMoved: 0 };
    this.log = []; this.fxq = []; this.physMs = 0;
    this.vr = mulberry32(4242);
    this.onForceBound = (ev) => this.onForce(ev);

    this.buildStatic();
    this.buildWall();
    this.buildCar();
    const D = Math.max(2, wallFront - (this.layout.carRear + c.carLength));
    this.accel = (c.speed * c.speed) / (2 * 0.8 * D);
    const hMax = Math.max(2.5, c.wallRows * c.brickH + 0.6, c.carHeight + 0.6);
    fitShadow(this.layout.carRear - 3, wallFront + 24, -this.layout.zB, this.layout.zB, 0, hMax);
    this.wallCenter = new THREE.Vector3(wallFront + (c.wallDepth * c.brickD) / 2, (c.wallRows * c.brickH) / 2, 0);
    this.addLog('Staged on the grid');
  }

  addLog(text) { this.log.push({ t: this.time, text }); if (this.log.length > 7) this.log.shift(); this.logDirty = true; }

  buildStatic() {
    const env = buildEnvironment(this.layout);
    this.envGroup = env.grp;
    scene.add(env.grp);
    const gb = this.world.createRigidBody(RAPIER.RigidBodyDesc.fixed());
    const gc = this.world.createCollider(RAPIER.ColliderDesc.cuboid(400, 0.5, 400).setTranslation(0, -0.5, 0).setFriction(this.cfg.groundFriction).setRestitution(0.05), gb);
    this.owners.set(gc.handle, { kind: 'ground' });
    for (const b of env.colliders) {
      const cc = this.world.createCollider(RAPIER.ColliderDesc.cuboid(b.h[0], b.h[1], b.h[2]).setTranslation(b.c[0], b.c[1], b.c[2]).setFriction(0.6).setRestitution(0.2), gb);
      this.owners.set(cc.handle, { kind: 'static' });
    }
  }

  track(body, obj, he, blob, im = null, idx = 0) {
    const t = body.translation(), q = body.rotation();
    const r = { body, obj, im, idx, he, blob, alive: true,
      px: t.x, py: t.y, pz: t.z, qx: q.x, qy: q.y, qz: q.z, qw: q.w,
      cx: t.x, cy: t.y, cz: t.z, cqx: q.x, cqy: q.y, cqz: q.z, cqw: q.w };
    this.tracked.push(r);
    if (obj) { obj.position.set(t.x, t.y, t.z); obj.quaternion.set(q.x, q.y, q.z, q.w); }
    return r;
  }

  buildWall() {
    const c = this.cfg, L = this.layout;
    const w = c.brickW, h = c.brickH, d = c.brickD;
    const gap = Math.min(0.004, w * 0.02);
    const mort = Math.min(0.012, Math.min(w, h, d) * 0.07);
    const Ww = c.wallCols * w;
    const list = [];
    for (let k = 0; k < c.wallDepth; k++) for (let r = 0; r < c.wallRows; r++) {
      const off = (r + k) % 2 === 1;
      const x = L.wallFront + d / 2 + k * (d + 0.004), y = h / 2 + r * h;
      if (!off) for (let i = 0; i < c.wallCols; i++) list.push({ x, y, z: -Ww / 2 + w / 2 + i * w, half: false });
      else {
        list.push({ x, y, z: -Ww / 2 + w / 4, half: true });
        for (let i = 0; i < c.wallCols - 1; i++) list.push({ x, y, z: -Ww / 2 + w + i * w, half: false });
        list.push({ x, y, z: Ww / 2 - w / 4, half: true });
      }
    }
    const nFull = list.filter((b) => !b.half).length, nHalf = list.length - nFull;
    const rad = Math.max(0, Math.min(0.012, (Math.min(w / 2, h, d) - mort) * 0.15));
    const meshF = new THREE.InstancedMesh(new RoundedBoxGeometry(d - mort, h - mort, w - mort, 2, rad), M.brick, Math.max(1, nFull));
    const meshH = new THREE.InstancedMesh(new RoundedBoxGeometry(d - mort, h - mort, w / 2 - mort, 2, rad), M.brick, Math.max(1, nHalf));
    meshF.count = nFull; meshH.count = nHalf;
    for (const m of [meshF, meshH]) { m.castShadow = true; m.receiveShadow = true; m.frustumCulled = false; this.group.add(m); }
    this.brickMeshes = [meshF, meshH];
    const pal = [0x8e3b2a, 0x9c4630, 0xa8523a, 0x7d3326, 0xb25c40, 0x6e2e22, 0x94412d];
    const pr = mulberry32(7), col = new THREE.Color();
    const CFE = RAPIER.ActiveEvents.CONTACT_FORCE_EVENTS;
    let iF = 0, iH = 0;
    for (const b of list) {
      const bw = b.half ? w / 2 : w, m = b.half ? c.brickMass / 2 : c.brickMass;
      const body = this.world.createRigidBody(RAPIER.RigidBodyDesc.dynamic().setTranslation(b.x, b.y, b.z).setCcdEnabled(true));
      const cd = RAPIER.ColliderDesc.cuboid(d / 2 - 0.001, h / 2, bw / 2 - gap / 2).setMass(m)
        .setFriction(c.brickFriction).setRestitution(c.brickRestitution)
        .setActiveEvents(CFE).setContactForceEventThreshold(Math.max(250, m * 9.81 * 30));
      const cc = this.world.createCollider(cd, body);
      const mesh = b.half ? meshH : meshF, idx = b.half ? iH++ : iF++;
      const rec = { body, x0: b.x, y0: b.y, z0: b.z, m };
      this.owners.set(cc.handle, { kind: 'brick', ref: rec });
      col.setHex(pal[(pr() * pal.length) | 0]).multiplyScalar(0.86 + pr() * 0.28);
      if (pr() < 0.06) col.multiplyScalar(0.55);
      mesh.setColorAt(idx, col);
      rec.track = this.track(body, null, [d / 2, h / 2, bw / 2], 0.42, mesh, idx);
      this.bricks.push(rec);
    }
    for (const m of [meshF, meshH]) if (m.instanceColor) m.instanceColor.needsUpdate = true;
    this.dustThresh = Math.max(400, c.brickMass * 9.81 * 40);
  }

  S3(v) { return [v[0] * this.sc.sx, v[1] * this.sc.sy, v[2] * this.sc.sz]; }

  buildCar() {
    const c = this.cfg;
    const sx = c.carLength / 4.2, sy = c.carHeight / 1.45, sz = c.carWidth / 1.8;
    this.sc = { sx, sy, sz, st: (sx + sy) / 2, sm: Math.min(sx, sy, sz) };
    this.carBase = [this.layout.carRear + c.carLength / 2, 0.004, this.layout.carZ];
    this.crushMax = TPL.CRUSH * sx;
    this.crushForce = 20 * c.carMass;
    this.strScale = Math.sqrt(c.carMass / 1250);
    this.brakeTorque = 1800 * (c.carMass / 1250);
    for (const sp of carSpec()) this.makePart(sp);
    this.cabin = this.partById.cabin;
    this.bondParts = this.parts.filter((p) => p.spec.bond);
    this.detachables = this.bondParts.filter((p) => !p.pane).length;
    this.paneCount = this.parts.filter((p) => p.pane).length;
    this.wheels = this.parts.filter((p) => p.spec.wheel);
    const bf = this.partById.bumperF;
    bf.frontOff = 2.10 * sx - bf.origin[0];
    this.rel0x = this.partById.nose.origin[0] - this.partById.front.origin[0];
  }

  makePart(sp) {
    const { sx, sy, sz, st } = this.sc;
    const part = { id: sp.id, spec: sp, mass: sp.mf * this.cfg.carMass, alive: true, fc: 0, dmg: 0, lastLoad: 0, stageIdx: 0, stage: 'perm', v0x: 0, v0y: 0, v0z: 0 };
    const cols = [];
    const bmin = [Infinity, Infinity, Infinity], bmax = [-Infinity, -Infinity, -Infinity];
    const grow = (c, h) => { for (let i = 0; i < 3; i++) { bmin[i] = Math.min(bmin[i], c[i] - h[i]); bmax[i] = Math.max(bmax[i], c[i] + h[i]); } };
    if (sp.pane) {
      const pts = sp.pane.pts.map((p) => new THREE.Vector3(...this.S3(p)));
      const e1 = pts[1].clone().sub(pts[0]), e2 = pts[2].clone().sub(pts[0]);
      const u = e1.clone().normalize(), n = e1.clone().cross(e2).normalize(), v = n.clone().cross(u);
      const O = new THREE.Vector3();
      pts.forEach((p) => O.add(p)); O.multiplyScalar(1 / pts.length);
      let poly = pts.map((p) => { const d = p.clone().sub(O); return [d.dot(u), d.dot(v)]; });
      const c2 = polyCentroid(poly);
      O.addScaledVector(u, c2[0]).addScaledVector(v, c2[1]);
      poly = poly.map((q) => [q[0] - c2[0], q[1] - c2[1]]);
      const th = sp.pane.th * st;
      part.pane = { u, v, n, poly, th, cells: voronoi2D(poly, sp.pane.n, sp.pane.seed), area: Math.abs(polyArea(poly)) };
      part.origin = [O.x, O.y, O.z];
      const hull = [];
      for (const q of poly) for (const sg of [-0.5, 0.5]) {
        const P = u.clone().multiplyScalar(q[0]).addScaledVector(v, q[1]).addScaledVector(n, th * sg);
        hull.push(P.x, P.y, P.z);
        grow([O.x + P.x, O.y + P.y, O.z + P.z], [0, 0, 0]);

      boxB(M.trim, 0.92, 1.68, 0.34, 0.70, 0.60, 0.64);
      box(M.trim, 0.98, 1.66, 0.22, 0.26, -0.55, 0.55);
      break;
    }
    case 'nose': {
      box(M.paint, 1.90, 1.99, 0.30, 0.80, -0.76, 0.76, 0.04);
      box(M.trim, 1.984, 1.998, 0.40, 0.60, -0.40, 0.40, 0.01);
      for (let k = 0; k < 3; k++) box(M.chrome, 1.996, 2.003, 0.44 + k * 0.06, 0.452 + k * 0.06, -0.38, 0.38);
      boxB(M.head, 1.955, 2.0, 0.62, 0.74, 0.44, 0.72, 0.02);
      boxB(M.chrome, 1.948, 1.958, 0.612, 0.748, 0.435, 0.726);
      box(M.engine, 1.72, 1.80, 0.32, 0.72, -0.55, 0.55);
      box(M.engine, 1.82, 1.88, 0.36, 0.46, -0.70, 0.70);
      break;
    }
    case 'bumperF': {
      box(M.paint, 1.985, 2.10, 0.22, 0.52, -0.84, 0.84, 0.05);
      box(M.trim, 2.0, 2.112, 0.205, 0.255, -0.74, 0.74, 0.01);
      box(M.trim, 2.095, 2.106, 0.28, 0.40, -0.52, 0.52, 0.01);
      box(M.plate, 2.1, 2.11, 0.405, 0.50, -0.25, 0.25, 0.005);
      boxB(M.head, 2.09, 2.104, 0.30, 0.36, 0.58, 0.70, 0.01);
      break;
    }
    case 'bumperR': {
      box(M.paint, -2.10, -2.015, 0.24, 0.52, -0.84, 0.84, 0.045);
      box(M.trim, -2.112, -2.02, 0.22, 0.30, -0.62, 0.62, 0.01);
      box(M.plate, -2.108, -2.098, 0.36, 0.46, -0.25, 0.25, 0.005);
      boxB(M.tail, -2.104, -2.098, 0.44, 0.48, 0.62, 0.78);
      for (const s of [1, -1]) {
        const g = new THREE.CylinderGeometry(0.04 * sm, 0.04 * sm, 0.1 * sx, 16);
        g.rotateZ(Math.PI / 2); g.translate(-2.09 * sx, 0.265 * sy, 0.45 * s * sz);
        geo(M.chrome, g);
      }
      break;
    }
    case 'hood': {
      const p0 = [0.99 * sx, 0.865 * sy], p1 = [1.97 * sx, 0.835 * sy];
      const len = Math.hypot(p1[0] - p0[0], p1[1] - p0[1]), ang = Math.atan2(p1[1] - p0[1], p1[0] - p0[0]);
      const th = 0.028 * sy, wid = 1.66 * sz;
      const g = new THREE.BoxGeometry(len, th, wid, 30, 1, 12);
      const mesh = new THREE.Mesh(g, M.paint);
      mesh.castShadow = true; mesh.receiveShadow = true;
      const cx = (p0[0] + p1[0]) / 2 - p.origin[0], cy = (p0[1] + p1[1]) / 2 - p.origin[1];
      mesh.position.set(cx, cy, -p.origin[2]);
      mesh.rotation.z = ang;
      p.obj.add(mesh);
      p.hoodDef = { mesh, base: g.attributes.position.array.slice(), len, wid, th, ang, cx, cy, frozen: null };
      break;
    }
    case 'trunk': {
      slab(M.paint, [-1.30, 0.945], [-2.0, 0.93], 0.03, -0.80, 0.80, 0.012);
      box(M.trim, -2.0, -1.935, 0.945, 0.975, -0.74, 0.74, 0.01);
      break;
    }
  }
}

wheelVisual(p, bag) {
  const s = p.spec.side, R = p.wheelR, W = p.wheelHW * 2, rr = R * 0.64, sm = this.sc.sm;
  const pts = [[rr * 1.02, -W * 0.44], [R * 0.86, -W * 0.5], [R * 0.965, -W * 0.47], [R, -W * 0.36], [R, W * 0.36], [R * 0.965, W * 0.47], [R * 0.86, W * 0.5], [rr * 1.02, W * 0.44]]
    .map(([a, b]) => new THREE.Vector2(a, b));
  const tire = new THREE.LatheGeometry(pts, 44); tire.rotateX(Math.PI / 2); bag.add(M.rubber, tire, null);
  const barrel = new THREE.CylinderGeometry(rr, rr, W * 0.8, 36, 1, true); barrel.rotateX(Math.PI / 2); bag.add(M.rim, barrel, null);
  const face = new THREE.CylinderGeometry(rr * 0.97, rr * 0.97, 0.012, 36); face.rotateX(Math.PI / 2); face.translate(0, 0, s * W * 0.28); bag.add(M.disc, face, null);
  const lip = new THREE.TorusGeometry(rr, 0.012 * sm, 6, 40); lip.translate(0, 0, s * W * 0.40); bag.add(M.rim, lip, null);
  for (let k = 0; k < 5; k++) {
    const spk = new THREE.BoxGeometry(rr * 0.92, 0.055 * sm, 0.03 * sm);
    spk.translate(rr * 0.46, 0, 0); spk.rotateZ(k * Math.PI * 0.4 + 0.3); spk.translate(0, 0, s * W * 0.33);
    bag.add(M.rim, spk, null);
  }
  const hub = new THREE.CylinderGeometry(rr * 0.2, rr * 0.24, 0.05 * sm, 16); hub.rotateX(Math.PI / 2); hub.translate(0, 0, s * W * 0.34); bag.add(M.rim, hub, null);
  const disc = new THREE.CylinderGeometry(R * 0.5, R * 0.5, 0.02, 28); disc.rotateX(Math.PI / 2); disc.translate(0, 0, s * W * 0.08); bag.add(M.disc, disc, null);
}

// ---------------------------------------------------------------- fixed-step physics
step() {
  const t0 = performance.now();
  this.control();
  for (const p of this.bondParts) {
    if (!p.alive) continue;
    const v = p.body.linvel();
    p.v0x = v.x; p.v0y = v.y; p.v0z = v.z; p.fc = 0;
  }
  for (const r of this.tracked) {
    if (!r.alive) continue;
    r.px = r.cx; r.py = r.cy; r.pz = r.cz; r.qx = r.cqx; r.qy = r.cqy; r.qz = r.cqz; r.qw = r.cqw;
  }
  this.dustBudget = 3; this.sparkBudget = 2;
  this.world.step(this.eq);
  this.stepIndex++;
  this.time = this.stepIndex * DT;
  this.eq.drainContactForceEvents(this.onForceBound);
  if (this.phase === 'crash') { this.evaluateBonds(); this.measureG(); }
  this.updateCrush();
  for (const r of this.tracked) {
    if (!r.alive) continue;
    const t = r.body.translation(), q = r.body.rotation();
    r.cx = t.x; r.cy = t.y; r.cz = t.z; r.cqx = q.x; r.cqy = q.y; r.cqz = q.z; r.cqw = q.w;
  }
  this.stepEffects();
  if (this.stepIndex % 12 === 0) this.checkSettled();
  this.physMs = this.physMs * 0.9 + (performance.now() - t0) * 0.1;
}

frontX() { const bf = this.partById.bumperF; return bf.body.translation().x + bf.frontOff; }

control() {
  const t = this.stepIndex * DT;
  if (this.phase === 'idle') {
    if (t < IDLE_TIME) return;
    this.phase = 'drive'; this.driveStep = this.stepIndex;
    M.startLight.emissiveIntensity = 0;
    this.addLog('Launch');
  }
  if (this.phase === 'drive') {
    const td = (this.stepIndex - this.driveStep + 1) * DT;
    const v = Math.min(this.accel * td, this.cfg.speed);
    this.cmdV = v;
    for (const p of this.parts) {
      const b = p.body, lv = b.linvel();
      b.setLinvel({ x: v, y: lv.y, z: 0 }, true);
      b.setAngvel(p.spec.wheel ? { x: 0, y: 0, z: -v / p.wheelR } : { x: 0, y: 0, z: 0 }, true);
    }
    if (this.frontX() + v * DT * 1.5 >= this.layout.wallFront) {
      this.phase = 'crash'; this.releaseT = t; this.stats.impactSpeed = v;
      this.addLog(`Tow released at ${(v * 3.6).toFixed(1)} km/h`);
    }
    return;
  }
  if (this.phase !== 'crash') return;
  this.crushActuator();
  if (t - this.releaseT >= 0.12) this.brakes();
  for (const p of this.bondParts) if (p.alive && p.stage === 'hinge' && p.spec.bond.friction) this.hingeFriction(p);
}

// Coulomb friction in a sprung hinge so a popped panel stays where the impact left it.
hingeFriction(p) {
  const bd = p.spec.bond, par = p.parent, T = bd.friction * DT;
  const ax = qrot(par.body.rotation(), bd.hinge.axis[0], bd.hinge.axis[1], bd.hinge.axis[2]);
  const wa = p.body.angvel(), wb = par.body.angvel();
  const rel = (wa.x - wb.x) * ax.x + (wa.y - wb.y) * ax.y + (wa.z - wb.z) * ax.z;
  const J = clamp(-rel * p.hingeI, -T, T);
  if (J === 0) return;
  p.body.applyTorqueImpulse({ x: ax.x * J, y: ax.y * J, z: ax.z * J }, true);
  par.body.applyTorqueImpulse({ x: -ax.x * J, y: -ax.y * J, z: -ax.z * J }, true);
}

comWorld(p) {
  const t = p.body.translation(), r = qrot(p.body.rotation(), p.localCom[0], p.localCom[1], p.localCom[2]);
  return { x: t.x + r.x, y: t.y + r.y, z: t.z + r.z };
}

// Plastic crumple zone: the nose slides back along the front clip against a capped crush force.
crushActuator() {
  const n = this.partById.nose, f = this.partById.front;
  const ax = qrot(f.body.rotation(), 1, 0, 0);
  const cn = this.comWorld(n), cf = this.comWorld(f);
  const vn = n.body.linvel(), vf = f.body.linvel(), wf = f.body.angvel();
  const rx = cn.x - cf.x, ry = cn.y - cf.y, rz = cn.z - cf.z;
  const px = vf.x + wf.y * rz - wf.z * ry, py = vf.y + wf.z * rx - wf.x * rz, pz = vf.z + wf.x * ry - wf.y * rx;
  const u = (vn.x - px) * ax.x + (vn.y - py) * ax.y + (vn.z - pz) * ax.z;
  const mu = (n.mass * f.mass) / (n.mass + f.mass);
  const atLimit = this.crushD >= this.crushMax - 0.002 && u < 0;
  const cap = this.crushForce * DT;
  const J = atLimit ? -mu * u : clamp(-mu * u, -cap, cap);
  if (Math.abs(J) < 1e-6) return;
  n.body.applyImpulse({ x: ax.x * J, y: ax.y * J, z: ax.z * J }, true);
  f.body.applyImpulseAtPoint({ x: -ax.x * J, y: -ax.y * J, z: -ax.z * J }, cn, true);
}

brakes() {
  const T = this.brakeTorque * DT;
  for (const w of this.wheels) {
    if (!w.alive || w.stage === 'free') continue;
    const par = w.parent, ax = qrot(par.body.rotation(), 0, 0, 1);
    const ww = w.body.angvel(), wp = par.body.angvel();
    const rel = (ww.x - wp.x) * ax.x + (ww.y - wp.y) * ax.y + (ww.z - wp.z) * ax.z;
    const J = clamp(-rel * 0.5 * w.mass * w.wheelR * w.wheelR, -T, T);
    w.body.applyTorqueImpulse({ x: ax.x * J, y: ax.y * J, z: ax.z * J }, true);
    par.body.applyTorqueImpulse({ x: -ax.x * J, y: -ax.y * J, z: -ax.z * J }, true);
  }
}

measureG() {
  if (this.impactT === null || this.time - this.impactT > 1.5) return;
  this.aHist.push(this.cabin.body.linvel());
  if (this.aHist.length > 7) this.aHist.shift();
  if (this.aHist.length < 7) return;
  const a = this.aHist[0], b = this.aHist[6];
  const g = Math.hypot(b.x - a.x, b.y - a.y, b.z - a.z) / (6 * DT) / 9.81;
  if (g > this.stats.peakG) this.stats.peakG = g;
}

onForce(ev) {
  const a = this.owners.get(ev.collider1()), b = this.owners.get(ev.collider2());
  if (!a || !b) return;
  const F = ev.totalForceMagnitude();
  if (a.kind === 'part') a.ref.fc += F;
  if (b.kind === 'part') b.ref.fc += F;
  const pb = a.kind === 'part' && b.kind === 'brick' ? [a, b] : b.kind === 'part' && a.kind === 'brick' ? [b, a] : null;
  if (pb && this.impactT === null && this.phase === 'crash') { this.impactT = this.time; this.onImpact(); }
  if (F < this.dustThresh) return;
  if (a.kind === 'brick' || b.kind === 'brick') {
    const br = a.kind === 'brick' ? a : b, other = br === a ? b : a;
    if ((other.kind === 'ground' || other.kind === 'brick' || other.kind === 'static') && this.dustBudget > 0) {
      this.dustBudget--;
      this.fxq.push(['dust', br.ref.body.translation(), F]);
    }
  }
  if (F > 2500 && this.sparkBudget > 0) {
    let part = null, at = null;
    if (pb) { part = pb[0].ref; const t1 = part.body.translation(), t2 = pb[1].ref.body.translation(); at = { x: (t1.x + t2.x) / 2, y: (t1.y + t2.y) / 2, z: (t1.z + t2.z) / 2 }; }
    else {
      const pp = a.kind === 'part' && (b.kind === 'ground' || b.kind === 'static') ? a : b.kind === 'part' && (a.kind === 'ground' || a.kind === 'static') ? b : null;
      if (pp) { part = pp.ref; const t1 = part.body.translation(); at = { x: t1.x, y: Math.max(0.04, t1.y - part.he[1] * 0.8), z: t1.z }; }
    }
    if (part && !part.spec.wheel && !part.pane) { this.sparkBudget--; this.fxq.push(['spark', at, F]); }
  }
}

onImpact() {
  const c = this.cfg, L = this.layout, rnd = this.vr;
  this.shake = Math.min(1, 0.5 + c.speed / 40);
  this.addLog(`Impact at ${(Math.hypot(this.cabin.body.linvel().x, this.cabin.body.linvel().z) * 3.6).toFixed(1)} km/h`);
  const hw = (c.carWidth / 2) * 0.9, wh = Math.min(c.wallRows * c.brickH, c.carHeight);
  for (let i = 0; i < 90; i++) {
    const z = L.carZ + (rnd() * 2 - 1) * hw, y = 0.1 + rnd() * wh;
    const tint = 0.85 + rnd() * 0.2;
    dust.emit(L.wallFront - 0.1, y, z, -1.2 - rnd() * 3.5, 0.4 + rnd() * 1.6, (rnd() * 2 - 1) * 2.4,
      1.6 + rnd() * 1.8, 0.25 + rnd() * 0.25, 1.4 + rnd() * 1.4, 0.55, 0.62 * tint, 0.47 * tint, 0.38 * tint, 1.6, -0.15);
  }
  for (let i = 0; i < 70; i++) {
    const z = L.carZ + (rnd() * 2 - 1) * hw, y = 0.25 + rnd() * 0.5, sp = 4 + rnd() * 9;
    const a = rnd() * Math.PI * 2;
    sparks.emit(L.wallFront - 0.05, y, z, -sp * 0.6 * rnd(), Math.abs(Math.sin(a)) * sp * 0.7 + 1, Math.cos(a) * sp,
      0.35 + rnd() * 0.5, 0.05, 0.02, 1.6, 1.0, 0.62 + rnd() * 0.25, 0.25, 0.8, 9.81);
  }
}

// ---------------------------------------------------------------- breakable bonds
evaluateBonds() {
  const g = this.cfg.gravity, crushFrac = this.crushD / this.crushMax;
  for (const p of this.bondParts) {
    if (!p.alive || p.stage === 'free') continue;
    const v = p.body.linvel();
    const load = p.mass * Math.hypot((v.x - p.v0x) / DT, (v.y - p.v0y) / DT + g, (v.z - p.v0z) / DT) + p.fc;
    p.lastLoad = load;
    const bd = p.spec.bond, th = p.stage === 'hinge' ? bd.H : bd.F, k = bd.structural ? this.strScale : 1;
    const yieldF = th[0] * k, cap = th[1] * k, ult = th[2] * k;
    if (load > yieldF) p.dmg += (load - yieldF) * DT;
    let reason = null;
    if (load > ult) reason = 'overload';
    else if (p.dmg > cap) reason = 'fatigue';
    else if (p.stage === 'fixed' && bd.strain && crushFrac >= bd.strain) reason = 'crush strain';
    else if (p.spec.host) { const h = this.partById[p.spec.host]; if (h.stage === 'free' || h.lastLoad > 7000) reason = 'door frame'; }
    else if (p.stage === 'hinge' && bd.maxAngle && this.hingeAngle(p) > bd.maxAngle) reason = 'over-rotation';
    if (reason) this.advanceBond(p, reason);
  }
}

hingeAngle(p) {
  const a = p.parent.body.rotation(), b = p.body.rotation();
  return 2 * Math.acos(Math.min(1, Math.abs(a.w * b.w + a.x * b.x + a.y * b.y + a.z * b.z)));
}

worldPoint(p, c) {
  const t = p.body.translation(), r = qrot(p.body.rotation(), c[0] - p.origin[0], c[1] - p.origin[1], c[2] - p.origin[2]);
  return { x: t.x + r.x, y: t.y + r.y, z: t.z + r.z };
}

advanceBond(p, reason) {
  const bd = p.spec.bond;
  if (p.joint) { this.world.removeImpulseJoint(p.joint, true); p.joint = null; }
  p.dmg = 0;
  if (p.pane) { this.shatter(p, reason); return; }
  const next = bd.stages[p.stageIdx + 1];
  p.stageIdx++;
  if (next === 'hinge') {
    p.stage = 'hinge';
    const par = p.parent, at = this.S3(bd.hinge.at), ax = bd.hinge.axis;
    const a1 = { x: at[0] - par.origin[0], y: at[1] - par.origin[1], z: at[2] - par.origin[2] };
    const a2 = { x: at[0] - p.origin[0], y: at[1] - p.origin[1], z: at[2] - p.origin[2] };
    p.joint = this.world.createImpulseJoint(RAPIER.JointData.revolute(a1, a2, { x: ax[0], y: ax[1], z: ax[2] }), par.body, p.body, true);
    p.joint.setContactsEnabled(true);
    const rx = p.origin[0] + p.localCom[0] - at[0], ry = p.origin[1] + p.localCom[1] - at[1], rz = p.origin[2] + p.localCom[2] - at[2];
    const along = rx * ax[0] + ry * ax[1] + rz * ax[2];
    p.hingeI = 0.9 * p.mass * Math.max(1e-3, rx * rx + ry * ry + rz * rz - along * along);
    if (p.id === 'hood') this.rebuildHood(p);
    if (bd.pop) {
      const pw = this.worldPoint(p, this.S3(bd.pop.at)), dir = qrot(p.body.rotation(), bd.pop.dir[0], bd.pop.dir[1], bd.pop.dir[2]);
      const J = p.mass * bd.pop.dv;
      p.body.applyImpulseAtPoint({ x: dir.x * J, y: dir.y * J, z: dir.z * J }, pw, true);
    }
    this.addLog(`${p.spec.label} unlatched · ${reason}`);
  } else {
    p.stage = 'free';
    this.stats.detached++;
    this.addLog(`${p.spec.label} torn off · ${reason}`);
  }
}

shatter(p, reason) {
  p.alive = false; p.stage = 'free'; p.rec.alive = false;
  const t = p.body.translation(), q = p.body.rotation(), lv = p.body.linvel(), av = p.body.angvel();
  for (const c of p.colliders) this.owners.delete(c.handle);
  this.world.removeRigidBody(p.body);
  this.group.remove(p.obj);
  disposeObj(p.obj);
  const pn = p.pane, qT = new THREE.Quaternion(q.x, q.y, q.z, q.w), T = new THREE.Vector3(t.x, t.y, t.z);
  const nW = pn.n.clone().applyQuaternion(qT);
  let made = 0;
  for (const cell of pn.cells) {
    const cc = polyCentroid(cell);
    const shr = cell.map((v) => [cc[0] + (v[0] - cc[0]) * 0.97, cc[1] + (v[1] - cc[1]) * 0.97]);
    const area = Math.abs(polyArea(shr));
    if (area < 1e-4) continue;
    const hull = [], top = [], bot = [];
    for (const v of shr) {
      const P = pn.u.clone().multiplyScalar(v[0] - cc[0]).addScaledVector(pn.v, v[1] - cc[1]);
      const A = P.clone().addScaledVector(pn.n, pn.th / 2), B = P.clone().addScaledVector(pn.n, -pn.th / 2);
      top.push(A); bot.push(B);
      hull.push(A.x, A.y, A.z, B.x, B.y, B.z);
    }
    const cd = RAPIER.ColliderDesc.convexHull(new Float32Array(hull));
    if (!cd) continue;
    const r = pn.u.clone().multiplyScalar(cc[0]).addScaledVector(pn.v, cc[1]).applyQuaternion(qT);
    const wc = T.clone().add(r);
    const rl = Math.max(1e-4, r.length());
    const vx = lv.x + av.y * r.z - av.z * r.y + (r.x / rl) * 0.3 + nW.x * 0.12;
    const vy = lv.y + av.z * r.x - av.x * r.z + (r.y / rl) * 0.3 + nW.y * 0.12;
    const vz = lv.z + av.x * r.y - av.y * r.x + (r.z / rl) * 0.3 + nW.z * 0.12;
    const bb = this.world.createRigidBody(RAPIER.RigidBodyDesc.dynamic().setTranslation(wc.x, wc.y, wc.z).setRotation(q)
      .setLinvel(vx, vy, vz).setAngvel(av).setCcdEnabled(true).setAngularDamping(0.2));
    cd.setMass(Math.max(0.02, p.mass * (area / pn.area))).setFriction(0.4).setRestitution(0.1);
    const col = this.world.createCollider(cd, bb);
    this.owners.set(col.handle, { kind: 'shard' });
    const mesh = new THREE.Mesh(prismGeo(top, bot), M.glass);
    mesh.castShadow = true;
    this.group.add(mesh);
    this.shards.push({ body: bb, mesh, rec: this.track(bb, mesh, [0.05, 0.05, 0.05], 0) });
    made++;
  }
  this.stats.panes++; this.stats.shards += made;
  this.addLog(`${p.spec.label} shattered · ${made} shards`);
  const rnd = this.vr;
  for (let i = 0; i < 16; i++) sparks.emit(t.x + (rnd() - 0.5) * 0.6, t.y + (rnd() - 0.5) * 0.3, t.z + (rnd() - 0.5) * 0.6,
    (rnd() - 0.5) * 3, rnd() * 2, (rnd() - 0.5) * 3, 0.25 + rnd() * 0.3, 0.03, 0.01, 1.1, 0.75, 0.9, 1.0, 1.5, 6);
}

tentH(len, d) { return 0.5 * Math.sqrt(Math.max(0, len * len - (len - d) * (len - d))) * 0.85; }

// After the latch lets go, the buckled hood gets a matching two-slab collider.
rebuildHood(p) {
  const hd = p.hoodDef;
  hd.frozen = this.dVis;
  const d = Math.min(hd.frozen, hd.len * 0.6), tent = this.tentH(hd.len, d);
  if (tent < 0.01) return;
  for (const c of p.colliders) { this.owners.delete(c.handle); this.world.removeCollider(c, false); }
  p.colliders = [];
  const C = 0.56, L2 = hd.len - d, ca = Math.cos(hd.ang), sa = Math.sin(hd.ang);
  const pts = [[-hd.len / 2, 0], [-hd.len / 2 + C * L2, tent], [-hd.len / 2 + L2, 0]];
  const CFE = RAPIER.ActiveEvents.CONTACT_FORCE_EVENTS;
  for (let i = 0; i < 2; i++) {
    const a = pts[i], b = pts[i + 1];
    const mx = (a[0] + b[0]) / 2, my = (a[1] + b[1]) / 2, len = Math.hypot(b[0] - a[0], b[1] - a[1]);
    const ang = hd.ang + Math.atan2(b[1] - a[1], b[0] - a[0]);
    const cx = hd.cx + mx * ca - my * sa, cy = hd.cy + mx * sa + my * ca;
    const cd = RAPIER.ColliderDesc.cuboid(len / 2, (0.03 * this.sc.st) / 2, hd.wid / 2)
      .setTranslation(cx, cy, -p.origin[2]).setRotation({ x: 0, y: 0, z: Math.sin(ang / 2), w: Math.cos(ang / 2) })
      .setMass(p.mass / 2).setFriction(0.5).setRestitution(0.12).setActiveEvents(CFE).setContactForceEventThreshold(300);
    const col = this.world.createCollider(cd, p.body);
    this.owners.set(col.handle, { kind: 'part', ref: p });
    p.colliders.push(col);
  }
  this.deformHood();
}

updateCrush() {
  const n = this.partById.nose, f = this.partById.front;
  const pn = n.body.translation(), pf = f.body.translation();
  const rel = qrot(qconj(f.body.rotation()), pn.x - pf.x, pn.y - pf.y, pn.z - pf.z);
  this.crushD = clamp(this.rel0x - rel.x, 0, this.crushMax);
  if (this.crushD > this.dVis) this.dVis = this.crushD;
}

// ---------------------------------------------------------------- visual-only effects (seeded, never fed back)
stepEffects() {
  const rnd = this.vr;
  this.shake *= Math.exp(-DT * 2.4);
  if (this.phase !== 'idle' && this.stepIndex % 2 === 0) {
    for (const w of this.wheels) {
      const t = w.body.translation(), R = w.wheelR;
      const ax = qrot(w.body.rotation(), 0, 0, 1);
      if (t.y - R > 0.04 || Math.abs(ax.y) > 0.35) { w.skidPrev = null; continue; }
      const v = w.body.linvel(), av = w.body.angvel();
      const slip = Math.hypot(v.x + av.z * R, v.z - av.x * R);
      if (w.skidPrev && slip > 2) {
